const root = document.querySelector('#site');
root.innerHTML = `${header}${pages[currentPage] || pages.notfound}${footer}`;

const navToggle = document.querySelector('.nav-toggle');
const navLinks = document.querySelector('.nav-links');
navToggle?.addEventListener('click', () => {
  const open = navLinks.classList.toggle('open');
  navToggle.setAttribute('aria-expanded', String(open));
});

const orb = document.querySelector('.orb');
let demoTimers = [];
orb?.addEventListener('click', () => {
  const sheet = document.querySelector('.task-sheet');
  const steps = [...document.querySelectorAll('.sheet-flow span')];
  const resultTitle = document.querySelector('.sheet-result strong');
  const resultText = document.querySelector('.sheet-result p');
  demoTimers.forEach(clearTimeout);
  demoTimers = [];
  const running = orb.classList.toggle('is-listening');
  sheet?.classList.toggle('is-active', running);
  steps.forEach((step) => step.classList.remove('is-current'));
  orb.setAttribute('aria-label', running ? 'Остановить демонстрацию задачи' : 'Воспроизвести демонстрацию задачи');
  if (!running) {
    resultTitle.textContent = 'Готово';
    resultText.textContent = 'Презентация сохранена · напоминание на 18:00';
    return;
  }
  resultTitle.textContent = 'Выполняю';
  resultText.textContent = 'Сейчас появятся этапы задачи';
  steps[0]?.classList.add('is-current');
  steps.slice(1).forEach((step, index) => {
    demoTimers.push(setTimeout(() => {
      steps.forEach((item) => item.classList.remove('is-current'));
      step.classList.add('is-current');
    }, (index + 1) * 900));
  });
  demoTimers.push(setTimeout(() => {
    steps.forEach((step) => step.classList.remove('is-current'));
    orb.classList.remove('is-listening');
    sheet?.classList.remove('is-active');
    orb.setAttribute('aria-label', 'Воспроизвести демонстрацию задачи');
    resultTitle.textContent = 'Готово';
    resultText.textContent = 'Презентация сохранена · напоминание на 18:00';
  }, 3000));
});

const accountForm = document.querySelector('[data-account-form]');
accountForm?.addEventListener('submit', (event) => {
  event.preventDefault();
  accountForm.reset();
  accountForm.querySelector('.form-message').textContent = 'Production-вход ещё не подключён. Данные не отправлены.';
});

const consentKey = 'troika_cookie_consent_v1';
const cookieUI = document.createElement('div');
cookieUI.innerHTML = `
  <section class="cookie-banner" role="region" aria-label="Настройки cookie" hidden>
    <p><strong>Cookie без слежки.</strong> Сейчас сайт хранит только ваш выбор. Аналитика и реклама не загружаются без согласия. <a href="/cookies/">Подробнее</a></p>
    <div class="cookie-actions"><button type="button" data-essential>Только необходимые</button><button type="button" data-custom>Настроить</button><button class="accept" type="button" data-accept>Разрешить все</button></div>
  </section>
  <div class="dialog-backdrop" hidden>
    <section class="cookie-dialog" role="dialog" aria-modal="true" aria-labelledby="cookie-title">
      <h2 id="cookie-title">Настройки cookie</h2><p class="form-note">Необязательные категории сейчас не используются. Перед их подключением сайт запросит согласие заново.</p>
      <div class="choice"><div><strong>Необходимые</strong><div class="form-note">Безопасность и ваш выбор.</div></div><span class="switch on locked" aria-label="Всегда включены"></span></div>
      <div class="choice"><div><strong>Функциональные</strong><div class="form-note">Необязательные настройки.</div></div><button class="switch" type="button" role="switch" aria-checked="false" data-consent="functional"></button></div>
      <div class="choice"><div><strong>Аналитические</strong><div class="form-note">Агрегированная статистика.</div></div><button class="switch" type="button" role="switch" aria-checked="false" data-consent="analytics"></button></div>
      <div class="choice"><div><strong>Маркетинговые</strong><div class="form-note">Реклама и кампании.</div></div><button class="switch" type="button" role="switch" aria-checked="false" data-consent="marketing"></button></div>
      <div class="cookie-actions"><button type="button" data-dialog-essential>Только необходимые</button><button class="accept" type="button" data-save>Сохранить выбор</button></div>
    </section>
  </div>`;
document.body.append(cookieUI);
const banner = document.querySelector('.cookie-banner');
const backdrop = document.querySelector('.dialog-backdrop');
const switches = [...document.querySelectorAll('[data-consent]')];

function saveConsent(categories) {
  localStorage.setItem(consentKey, JSON.stringify({ ...categories, necessary: true, updatedAt: new Date().toISOString() }));
  banner.hidden = true;
  backdrop.hidden = true;
}
function openSettings() { backdrop.hidden = false; backdrop.querySelector('[data-save]').focus(); }
function essentialOnly() { saveConsent({ functional: false, analytics: false, marketing: false }); }

if (!localStorage.getItem(consentKey)) banner.hidden = false;
document.querySelector('[data-essential]')?.addEventListener('click', essentialOnly);
document.querySelector('[data-dialog-essential]')?.addEventListener('click', essentialOnly);
document.querySelector('[data-accept]')?.addEventListener('click', () => saveConsent({ functional: true, analytics: true, marketing: true }));
document.querySelector('[data-custom]')?.addEventListener('click', openSettings);
document.querySelectorAll('[data-cookie-settings]').forEach((button) => button.addEventListener('click', openSettings));
switches.forEach((button) => button.addEventListener('click', () => {
  const checked = button.getAttribute('aria-checked') === 'true';
  button.setAttribute('aria-checked', String(!checked));
  button.classList.toggle('on', !checked);
}));
document.querySelector('[data-save]')?.addEventListener('click', () => {
  const choice = Object.fromEntries(switches.map((button) => [button.dataset.consent, button.getAttribute('aria-checked') === 'true']));
  saveConsent(choice);
});
backdrop?.addEventListener('click', (event) => { if (event.target === backdrop) backdrop.hidden = true; });
document.addEventListener('keydown', (event) => { if (event.key === 'Escape' && !backdrop.hidden) backdrop.hidden = true; });
